trait Summary {
    fn summarize(&self) -> String;
}

struct Article {
    title: String,
}

impl Summary for Article {
    fn summarize(&self) -> String {
        format!("{}", self.title)
    }
}

fn main() {
    let article = Article { title: String::from("Campus power") };
    println!("{}", article.summarize());
}
